// The embedded approach catalog: the compiled procedure rows decoded on
// demand for picker and review use.
import Foundation

@MainActor final class ApproachCatalog: ObservableObject {
    static let shared = ApproachCatalog()
    @Published private(set) var procedures: [LoggedProcedure] = []
    @Published private(set) var loading = false
    @Published private(set) var message = ""
    private var expires = Date.distantPast
    init() {
        if let data = UserDefaults.standard.data(forKey: "approach-catalog-v1"),
           let saved = try? JSONDecoder().decode(Cache.self, from: data) { procedures = saved.procedures; expires = saved.expires }
        if procedures.isEmpty { procedures = Self.bundled }
    }
    struct Cache: Codable { let procedures: [LoggedProcedure]; let expires: Date }
    func choices(_ code: String) -> [LoggedProcedure] { Array(Dictionary(grouping: procedures.filter { $0.airport == AirportRoute.canonical(code) }, by: \.id).values.compactMap(\.first)).sorted { $0.name < $1.name } }
    func refresh() async {
        guard !loading, expires <= Date() else { return }
        loading = true; defer { loading = false }
        guard let page = URL(string: "https://aeronav.faa.gov/d-tpp/"), let data = try? await WebData.data(page),
              let html = String(data: data, encoding: .utf8) else { message = "Using saved procedures."; return }
        let cycles = Array(Set(WebData.matches(#"/d-tpp/(\d{4})/"#, in: html))).sorted(by: >).prefix(4)
        for cycle in cycles {
            guard let url = URL(string: "https://aeronav.faa.gov/d-tpp/\(cycle)/xml_data/d-tpp_Metafile.xml"),
                  let data = try? await WebData.data(url), !Task.isCancelled else { continue }
            guard let delegate = ProcedureXML.read(data), let effective = delegate.effective, let end = delegate.expires,
                  effective <= Date(), Date() < end, !delegate.procedures.isEmpty else { continue }
            procedures = delegate.procedures; expires = end; message = ""
            if let encoded = try? JSONEncoder().encode(Cache(procedures: procedures, expires: end)) {
                UserDefaults.standard.set(encoded, forKey: "approach-catalog-v1")
            }
            return
        }
        message = "Using saved procedures. Logging reference only."
    }
